import { useState } from 'react';
import {
  JxCard,
  JxStepper,
  JxStep,
  JxInput,
  JxButton,
  JxStack,
  JxHeading,
  JxText,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    street: '',
    city: '',
    postalCode: '',
  });

  const updateField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const isLastStep = currentStep === STEPS.length - 1;
  const isFirstStep = currentStep === 0;

  const goNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const goBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <JxCard className="jx-p-lg" style={{ maxWidth: 'var(--jx-size-2xl)' }}>
      <JxStack direction="column" gap="lg">
        <JxStepper activeStep={currentStep}>
          {STEPS.map((label) => (
            <JxStep key={label} label={label} />
          ))}
        </JxStepper>

        <JxDivider />

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Контакты</JxHeading>
            <JxInput
              label="Полное имя"
              value={data.fullName}
              onValueChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
            <JxInput
              label="Email"
              type="email"
              value={data.email}
              onValueChange={updateField('email')}
              placeholder="ivan@example.com"
            />
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Адрес</JxHeading>
            <JxInput
              label="Улица и дом"
              value={data.street}
              onValueChange={updateField('street')}
              placeholder="ул. Ленина, 10"
            />
            <JxInput
              label="Город"
              value={data.city}
              onValueChange={updateField('city')}
              placeholder="Москва"
            />
            <JxInput
              label="Почтовый индекс"
              value={data.postalCode}
              onValueChange={updateField('postalCode')}
              placeholder="123456"
            />
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxHeading level={3}>Проверка</JxHeading>
            <JxStack direction="column" gap="sm">
              <JxText weight="semibold">Контакты</JxText>
              <JxText>Имя: {data.fullName || '—'}</JxText>
              <JxText>Email: {data.email || '—'}</JxText>
            </JxStack>
            <JxDivider />
            <JxStack direction="column" gap="sm">
              <JxText weight="semibold">Адрес</JxText>
              <JxText>Улица: {data.street || '—'}</JxText>
              <JxText>Город: {data.city || '—'}</JxText>
              <JxText>Индекс: {data.postalCode || '—'}</JxText>
            </JxStack>
          </JxStack>
        )}

        <JxDivider />

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={goBack} disabled={isFirstStep}>
            Назад
          </JxButton>
          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={goNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

